INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.112.1',
  '2026-10-03',
  'Пульт ТВ: под карточками пусто, очередь собирается по кнопке',
  E'Под плитками в списке больше нет кнопок — только постер и название. Две кнопки под каждой карточкой растягивали сетку вдвое и оттесняли сами постеры, а нужны они были изредка.\n\n«Инфо» теперь открывается со страницы сериала или папки. У фильма своей страницы нет — карточка сразу его включает, поэтому его «Инфо» переехало в панель плеера, следом за «Сон»: нажали во время просмотра — видео встало на паузу, открылось описание с кадрами, «Назад» вернул к карточке.\n\n«В очередь» появляется только когда очередь собирают. В шапке, рядом с «Визуальный» и «Файлы», добавилась кнопка «＋ Создать очередь»: нажали — под плитками (и в общем списке, и внутри папки) появились кнопки «＋ В очередь», набрали что нужно, нажали «✔ Готово» — кнопки убрались. Сам раздел «Очередь» с кнопкой «Смотреть очередь» показывается как и раньше, пока очередь не пуста.',
  E'Кнопка «ℹ Инфо» из плитки убрана совсем (вместе с .ibtn и data-info в делегировании кликов). В панели плеера её действие — leavePlayer() плюс openInfo(playingTile): «Инфо» это отдельный экран, поэтому плеер приходится свернуть; место сохраняется обычным saveProgress.\n\nplayingTile — что играет как элемент медиатеки, а не как файл: ставится в playFilm, playSeriesFrom, playEpisode и resumeEntry (ключ записи «Продолжить просмотр» = id плитки), сбрасывается в startFrom (режим «Файлы») и в actions.stop. Пусто — кнопка скрыта.\n\nqueueMode живёт до перезагрузки страницы: сама очередь переживает её и так. Кнопка в шапке прячется в «Файлах» и в плеере (renderQueueMode зовётся из setMode, showPlayer и leavePlayer), переключение перерисовывает текущий экран на месте — renderHomeInPlace или renderCollInPlace, чтобы пульт не прыгал в начало.\n\nПроверено в браузере: карточки без кнопок, появление и исчезновение «＋ В очередь» по кнопке в шапке (в списке и внутри папки), «Инфо» из плеера для фильма и для серии сериала (открывается карточка сериала), скрытие кнопки в «Файлах» и возврат в визуальном, ход стрелками по сетке в обоих состояниях.'
);
